{"title":"Session tree (parent → subagent sessions)","type":"vega","aggs":[],"params":{"spec":"{
  "$schema": "https://vega.github.io/schema/vega/v5.json",
  "description": "Hermes ATP session tree: each request's parent session with the subagent sessions it delegated to. Node size = tokens, colour = time in model + tool calls, red ring = the session has a failed step. Sessions whose parent is outside the current filters/time range (or whose first record is filtered out) hang off the left edge.",
  "autosize": {
    "type": "fit",
    "contains": "padding"
  },
  "padding": 8,
  "signals": [
    {
      "name": "labelSpace",
      "update": "min(360, width * 0.45)"
    },
    {
      "name": "maxMs",
      "update": "length(data('shown')) ? extent(pluck(data('shown'), 'ms'))[1] : 0"
    },
    {
      "name": "maxTokens",
      "update": "length(data('shown')) ? extent(pluck(data('shown'), 'n_tokens'))[1] : 0"
    },
    {
      "name": "maxDepth",
      "update": "length(data('shown')) ? extent(pluck(data('shown'), 'depth'))[1] : 1"
    }
  ],
  "data": [
    {
      "name": "sessions",
      "url": {
        "%context%": true,
        "%timefield%": "@timestamp",
        "index": "hermes-atp-records-*",
        "body": {
          "size": 0,
          "aggs": {
            "sessions": {
              "terms": {
                "field": "session_id",
                "size": 500,
                "order": {
                  "first": "asc"
                }
              },
              "aggs": {
                "first": {
                  "min": {
                    "field": "@timestamp"
                  }
                },
                "last": {
                  "max": {
                    "field": "@timestamp"
                  }
                },
                "tokens": {
                  "sum": {
                    "field": "tokens.total"
                  }
                },
                "model_ms": {
                  "sum": {
                    "field": "api_duration_ms"
                  }
                },
                "tool_ms": {
                  "sum": {
                    "field": "duration_ms"
                  }
                },
                "model_calls": {
                  "filter": {
                    "term": {
                      "event": "post_api_request"
                    }
                  }
                },
                "tool_calls": {
                  "filter": {
                    "term": {
                      "event": "post_tool_call"
                    }
                  }
                },
                "errors": {
                  "filter": {
                    "bool": {
                      "should": [
                        {
                          "term": {
                            "event": "api_request_error"
                          }
                        },
                        {
                          "bool": {
                            "filter": [
                              {
                                "term": {
                                  "event": "post_tool_call"
                                }
                              }
                            ],
                            "must_not": [
                              {
                                "term": {
                                  "status": "ok"
                                }
                              }
                            ]
                          }
                        }
                      ],
                      "minimum_should_match": 1
                    }
                  }
                },
                "model": {
                  "terms": {
                    "field": "model",
                    "size": 1
                  }
                },
                "platform": {
                  "terms": {
                    "field": "platform",
                    "size": 1
                  }
                },
                "start": {
                  "filter": {
                    "term": {
                      "is_session_start": true
                    }
                  },
                  "aggs": {
                    "doc": {
                      "top_hits": {
                        "size": 1,
                        "_source": {
                          "includes": [
                            "parent_session_id",
                            "parent_turn_id",
                            "parent_subagent_id",
                            "task_id"
                          ]
                        }
                      }
                    }
                  }
                }
              }
            }
          }
        }
      },
      "format": {
        "property": "aggregations.sessions.buckets"
      },
      "transform": [
        {
          "type": "formula",
          "as": "id",
          "expr": "datum.key"
        },
        {
          "type": "formula",
          "as": "link",
          "expr": "datum.start.doc.hits.hits.length ? datum.start.doc.hits.hits[0]._source : {}"
        },
        {
          "type": "formula",
          "as": "declared_parent",
          "expr": "datum.link.parent_session_id || null"
        },
        {
          "type": "formula",
          "as": "t_first",
          "expr": "datum.first.value"
        },
        {
          "type": "formula",
          "as": "t_last",
          "expr": "datum.last.value"
        },
        {
          "type": "formula",
          "as": "n_tokens",
          "expr": "datum.tokens.value || 0"
        },
        {
          "type": "formula",
          "as": "ms",
          "expr": "(datum.model_ms.value || 0) + (datum.tool_ms.value || 0)"
        },
        {
          "type": "formula",
          "as": "n_errors",
          "expr": "datum.errors.doc_count"
        },
        {
          "type": "formula",
          "as": "model_name",
          "expr": "datum.model.buckets.length ? datum.model.buckets[0].key : ''"
        },
        {
          "type": "formula",
          "as": "platform_name",
          "expr": "datum.platform.buckets.length ? datum.platform.buckets[0].key : ''"
        }
      ]
    },
    {
      "name": "nodes",
      "source": "sessions",
      "transform": [
        {
          "type": "lookup",
          "from": "sessions",
          "key": "id",
          "fields": [
            "declared_parent"
          ],
          "as": [
            "prow"
          ]
        },
        {
          "type": "formula",
          "as": "parent",
          "expr": "datum.prow && datum.declared_parent !== datum.id ? datum.declared_parent : '__root__'"
        },
        {
          "type": "formula",
          "as": "orphan",
          "expr": "!!datum.declared_parent && !datum.prow"
        }
      ]
    },
    {
      "name": "top",
      "values": [
        {
          "id": "__root__",
          "parent": null,
          "t_first": 0
        }
      ]
    },
    {
      "name": "tree",
      "source": [
        "top",
        "nodes"
      ],
      "transform": [
        {
          "type": "stratify",
          "key": "id",
          "parentKey": "parent"
        },
        {
          "type": "tree",
          "method": "tidy",
          "separation": true,
          "sort": {
            "field": "t_first",
            "order": "ascending"
          },
          "size": [
            {
              "signal": "height"
            },
            {
              "signal": "width - labelSpace"
            }
          ],
          "as": [
            "y",
            "x",
            "depth",
            "children"
          ]
        }
      ]
    },
    {
      "name": "links",
      "source": "tree",
      "transform": [
        {
          "type": "treelinks"
        },
        {
          "type": "filter",
          "expr": "datum.source.id !== '__root__'"
        },
        {
          "type": "formula",
          "as": "sx",
          "expr": "scale('xdepth', datum.source.depth)"
        },
        {
          "type": "formula",
          "as": "tx",
          "expr": "scale('xdepth', datum.target.depth)"
        },
        {
          "type": "linkpath",
          "orient": "horizontal",
          "shape": "diagonal",
          "sourceX": "sx",
          "sourceY": "source.y",
          "targetX": "tx",
          "targetY": "target.y"
        }
      ]
    },
    {
      "name": "shown",
      "source": "tree",
      "transform": [
        {
          "type": "filter",
          "expr": "datum.id !== '__root__'"
        }
      ]
    }
  ],
  "scales": [
    {
      "name": "xdepth",
      "type": "linear",
      "domain": {
        "signal": "[1, max(2, maxDepth)]"
      },
      "range": [
        {
          "signal": "16"
        },
        {
          "signal": "max(32, width - labelSpace)"
        }
      ],
      "zero": false,
      "nice": false
    },
    {
      "name": "size",
      "type": "sqrt",
      "domain": {
        "signal": "[0, max(1, maxTokens)]"
      },
      "range": [
        60,
        900
      ]
    },
    {
      "name": "color",
      "type": "linear",
      "domain": {
        "signal": "[0, max(1, maxMs)]"
      },
      "range": {
        "scheme": "blues"
      }
    }
  ],
  "legends": [
    {
      "fill": "color",
      "type": "gradient",
      "title": "model + tool ms",
      "orient": "top-left",
      "direction": "horizontal",
      "gradientLength": 120
    }
  ],
  "marks": [
    {
      "type": "path",
      "from": {
        "data": "links"
      },
      "encode": {
        "update": {
          "path": {
            "field": "path"
          },
          "stroke": {
            "value": "#98a2b3"
          },
          "strokeWidth": {
            "value": 1.5
          }
        }
      }
    },
    {
      "type": "symbol",
      "from": {
        "data": "shown"
      },
      "encode": {
        "update": {
          "x": {
            "scale": "xdepth",
            "field": "depth"
          },
          "y": {
            "field": "y"
          },
          "size": {
            "scale": "size",
            "field": "n_tokens"
          },
          "fill": {
            "scale": "color",
            "field": "ms"
          },
          "stroke": [
            {
              "test": "datum.n_errors > 0",
              "value": "#d92d20"
            },
            {
              "value": "#344054"
            }
          ],
          "strokeWidth": [
            {
              "test": "datum.n_errors > 0",
              "value": 3
            },
            {
              "value": 1
            }
          ],
          "strokeDash": [
            {
              "test": "datum.orphan",
              "value": [
                3,
                2
              ]
            },
            {
              "value": []
            }
          ],
          "tooltip": {
            "signal": "{'session': datum.id, 'parent session': datum.declared_parent || '(none: top-level request)', 'parent turn': datum.link.parent_turn_id || '', 'parent subagent': datum.link.parent_subagent_id || '', 'task': datum.link.task_id || '', 'platform': datum.platform_name, 'model': datum.model_name, 'model calls': datum.model_calls.doc_count, 'tool calls': datum.tool_calls.doc_count, 'failed steps': datum.n_errors, 'tokens': format(datum.n_tokens, ','), 'model + tool ms': format(datum.ms, ','), 'first record': timeFormat(datum.t_first, '%Y-%m-%d %H:%M:%S'), 'elapsed s': format((datum.t_last - datum.t_first) / 1000, ',.0f'), 'records': datum.doc_count}"
          }
        }
      }
    },
    {
      "type": "text",
      "from": {
        "data": "shown"
      },
      "encode": {
        "update": {
          "x": {
            "scale": "xdepth",
            "field": "depth",
            "offset": 18
          },
          "y": {
            "field": "y"
          },
          "dy": [
            {
              "test": "datum.children > 0",
              "value": -14
            },
            {
              "value": 0
            }
          ],
          "baseline": {
            "value": "middle"
          },
          "fontSize": {
            "value": 11
          },
          "fill": {
            "value": "#101828"
          },
          "limit": {
            "signal": "labelSpace - 24"
          },
          "text": {
            "signal": "(length(datum.id) > 16 ? '…' + slice(datum.id, -14) : datum.id) + '  ' + (datum.platform_name === 'subagent' ? 'subagent' : (datum.platform_name || 'session')) + ' · ' + (datum.model_name || 'no model') + ' · ' + format(datum.n_tokens, ',') + ' tok · ' + format(datum.ms, ',') + ' ms'"
          }
        }
      }
    },
    {
      "type": "text",
      "encode": {
        "update": {
          "x": {
            "signal": "width / 2"
          },
          "y": {
            "signal": "height / 2"
          },
          "align": {
            "value": "center"
          },
          "fill": {
            "value": "#667085"
          },
          "fontSize": {
            "value": 13
          },
          "text": {
            "signal": "length(data('shown')) ? '' : 'No sessions in the selected time range / filters'"
          }
        }
      }
    }
  ]
}"}}

{"title":"Step waterfall","type":"vega","aggs":[],"params":{"spec":"{
  "$schema": "https://vega.github.io/schema/vega-lite/v5.json",
  "description": "Hermes ATP step waterfall: one bar per completed step (model call, tool call, API error), ending at the completion record's @timestamp and as long as its duration_ms / api_duration_ms. Rows: sessions in start order, then seq. A hollow diamond is a step that started (pre_*) but has no completion record in range (still running or crashed). Recorder timestamps are whole seconds, so bars are placed to the second; seq gives the exact order.",
  "autosize": {
    "type": "fit",
    "contains": "padding"
  },
  "data": {
    "url": {
      "%context%": true,
      "%timefield%": "@timestamp",
      "index": "hermes-atp-records-*",
      "body": {
        "size": 2000,
        "sort": [
          {
            "@timestamp": "asc"
          },
          {
            "source.line": "asc"
          },
          {
            "seq": "asc"
          }
        ],
        "_source": [
          "@timestamp",
          "session_id",
          "seq",
          "event",
          "action_type",
          "tool_name",
          "tool_call_id",
          "api_request_id",
          "model",
          "status",
          "status_code",
          "error_type",
          "duration_ms",
          "api_duration_ms",
          "tokens.total",
          "retry_count",
          "verify.status",
          "platform",
          "source.line"
        ]
      }
    },
    "format": {
      "property": "hits.hits"
    }
  },
  "transform": [
    {
      "calculate": "datum._source.session_id",
      "as": "session"
    },
    {
      "filter": "isValid(datum.session)"
    },
    {
      "calculate": "datum._source.seq",
      "as": "seq"
    },
    {
      "calculate": "datum._source.event",
      "as": "event"
    },
    {
      "calculate": "time(toDate(datum._source['@timestamp']))",
      "as": "end"
    },
    {
      "calculate": "datum._source.duration_ms != null ? datum._source.duration_ms : (datum._source.api_duration_ms != null ? datum._source.api_duration_ms : 0)",
      "as": "dur"
    },
    {
      "calculate": "datum.end - datum.dur",
      "as": "start"
    },
    {
      "calculate": "indexof(datum.event, 'tool') >= 0 ? 'tool' : 'model'",
      "as": "family"
    },
    {
      "calculate": "datum.family === 'tool' ? datum._source.tool_call_id : datum._source.api_request_id",
      "as": "step_id"
    },
    {
      "calculate": "datum.session + '|' + datum.family + '|' + datum.step_id",
      "as": "pair"
    },
    {
      "calculate": "datum._source.source ? datum._source.source.line : 0",
      "as": "line"
    },
    {
      "joinaggregate": [
        {
          "op": "min",
          "field": "end",
          "as": "session_start"
        },
        {
          "op": "min",
          "field": "line",
          "as": "session_line"
        }
      ],
      "groupby": [
        "session"
      ]
    },
    {
      "joinaggregate": [
        {
          "op": "count",
          "as": "pair_n"
        }
      ],
      "groupby": [
        "pair"
      ]
    },
    {
      "calculate": "indexof(datum.event, 'pre_') === 0",
      "as": "is_pre"
    },
    {
      "filter": "!datum.is_pre || datum.pair_n === 1 || !datum.step_id"
    },
    {
      "calculate": "datum.is_pre ? 'started, no completion' : datum.event",
      "as": "kind"
    },
    {
      "calculate": "datum._source.tool_name || datum._source.model || ''",
      "as": "what"
    },
    {
      "window": [
        {
          "op": "row_number",
          "as": "rank"
        }
      ],
      "sort": [
        {
          "field": "session_start"
        },
        {
          "field": "session_line"
        },
        {
          "field": "session"
        },
        {
          "field": "seq"
        }
      ]
    },
    {
      "calculate": "slice('00000' + datum.rank, -5) + '\\t' + (length(datum.session) > 16 ? '…' + slice(datum.session, -12) : datum.session) + ' #' + datum.seq + '  ' + datum.what",
      "as": "row"
    },
    {
      "calculate": "datum._source.status || (datum._source.status_code ? 'HTTP ' + datum._source.status_code : '')",
      "as": "status"
    },
    {
      "calculate": "datum._source.tokens ? datum._source.tokens.total : null",
      "as": "tokens"
    },
    {
      "calculate": "datum._source.verify ? datum._source.verify.status : ''",
      "as": "verify"
    }
  ],
  "encoding": {
    "y": {
      "field": "row",
      "type": "ordinal",
      "sort": "ascending",
      "axis": {
        "title": null,
        "labelLimit": 260,
        "labelFontSize": 10,
        "labelExpr": "split(datum.label, '\\t')[1]"
      }
    },
    "color": {
      "field": "kind",
      "type": "nominal",
      "title": "step",
      "scale": {
        "domain": [
          "post_api_request",
          "post_tool_call",
          "api_request_error",
          "started, no completion"
        ],
        "range": [
          "#2e90fa",
          "#12b76a",
          "#d92d20",
          "#f79009"
        ]
      },
      "legend": {
        "orient": "top"
      }
    },
    "tooltip": [
      {
        "field": "session",
        "title": "session"
      },
      {
        "field": "seq",
        "title": "seq"
      },
      {
        "field": "event",
        "title": "event"
      },
      {
        "field": "what",
        "title": "tool / model"
      },
      {
        "field": "status",
        "title": "status"
      },
      {
        "field": "dur",
        "title": "duration ms"
      },
      {
        "field": "tokens",
        "title": "tokens"
      },
      {
        "field": "verify",
        "title": "verify"
      },
      {
        "field": "end",
        "type": "temporal",
        "title": "recorded",
        "format": "%H:%M:%S"
      }
    ]
  },
  "layer": [
    {
      "transform": [
        {
          "filter": "!datum.is_pre"
        }
      ],
      "mark": {
        "type": "bar",
        "cornerRadius": 2,
        "minBandSize": 2
      },
      "encoding": {
        "x": {
          "field": "start",
          "type": "temporal",
          "title": null,
          "axis": {
            "format": "%H:%M:%S",
            "labelFontSize": 10
          }
        },
        "x2": {
          "field": "end"
        }
      }
    },
    {
      "transform": [
        {
          "filter": "datum.is_pre"
        }
      ],
      "mark": {
        "type": "point",
        "shape": "diamond",
        "filled": false,
        "size": 80,
        "strokeWidth": 2
      },
      "encoding": {
        "x": {
          "field": "end",
          "type": "temporal"
        }
      }
    }
  ]
}"}}
